"""Summarize `jfr print --json --stack-depth 128` output without third-party packages.

Expected events: jdk.ExecutionSample and jdk.ObjectAllocationSample. Inclusive
attribution counts each distinct (declaring class, method, descriptor) once per
stack, even for recursion. Allocation weights are sampled byte estimates.
"""

import argparse
from collections import Counter
import json
from pathlib import Path
import re
import sys


CPU_EVENT = "jdk.ExecutionSample"
ALLOCATION_EVENT = "jdk.ObjectAllocationSample"
DEFAULT_THREAD = r"(?i)(?:jmh-worker|BinaryWriterBenchmark)"
DEFAULT_STACK = r"(?:BinaryWriterBenchmark\.serialize|[A-Za-z0-9_$]*BinaryQueryResultWriter\.)"
PREFIX = re.compile(r'\A\s*\{\s*"recording"\s*:\s*\{\s*"events"\s*:\s*\[')
PRIMITIVES = {"B": "byte", "C": "char", "D": "double", "F": "float", "I": "int",
              "J": "long", "S": "short", "Z": "boolean"}


def iter_jfr_events(path, chunk_size=262144):
    """Stream the standard JDK recording/events envelope, retaining at most one event plus a chunk."""
    decoder = json.JSONDecoder()
    with Path(path).open(encoding="utf-8-sig") as source:
        buffer = ""
        while True:
            chunk = source.read(chunk_size)
            buffer += chunk
            match = PREFIX.match(buffer)
            if match:
                position = match.end()
                break
            if not chunk or len(buffer) > 1048576:
                raise ValueError('Expected JFR JSON envelope {"recording":{"events":[...]}}')
        first = True
        while True:
            while True:
                while position < len(buffer) and buffer[position].isspace():
                    position += 1
                if position < len(buffer):
                    break
                buffer = source.read(chunk_size)
                position = 0
                if not buffer:
                    raise ValueError("Truncated JFR events array")
            if buffer[position] == "]":
                tail = buffer[position + 1:] + source.read()
                if not re.fullmatch(r"\s*}\s*}\s*", tail):
                    raise ValueError("Unexpected content after JFR events array")
                return
            if not first:
                if buffer[position] != ",":
                    raise ValueError("Missing comma between JFR events")
                position += 1
            while True:
                while position < len(buffer) and buffer[position].isspace():
                    position += 1
                try:
                    event, end = decoder.raw_decode(buffer, position)
                    break
                except json.JSONDecodeError as failure:
                    chunk = source.read(chunk_size)
                    if not chunk:
                        raise ValueError(f"Invalid or truncated JFR event: {failure}") from failure
                    buffer = buffer[position:] + chunk
                    position = 0
            if not isinstance(event, dict):
                raise ValueError("JFR event must be an object")
            yield event
            position = end
            first = False
            if position >= chunk_size:
                buffer = buffer[position:]
                position = 0


def class_name(recorded_class):
    name = recorded_class.get("name", "<unknown class>") if isinstance(recorded_class, dict) else recorded_class
    if not isinstance(name, str):
        return "<unknown class>"
    dimensions = len(name) - len(name.lstrip("["))
    if dimensions:
        element = name[dimensions:]
        name = PRIMITIVES.get(element, element[1:-1] if element.startswith("L") and element.endswith(";") else element)
    return name.replace("/", ".") + "[]" * dimensions


def method_key(frame):
    method = frame.get("method") or {}
    return (class_name(method.get("type")) + "." + str(method.get("name", "<unknown method>")),
            str(method.get("descriptor", "")))


def percent(numerator, denominator):
    return round(100.0 * numerator / denominator, 4) if denominator else 0.0


def ranked_methods(counter, denominator, value_name):
    return [{"method": key[0], "descriptor": key[1], value_name: value,
             "percent_filtered": percent(value, denominator)}
            for key, value in sorted(counter.items(), key=lambda pair: (-pair[1], pair[0]))]


def summarize(events, thread_regex=DEFAULT_THREAD, stack_regex=DEFAULT_STACK):
    thread_pattern, stack_pattern = re.compile(thread_regex), re.compile(stack_regex)
    event_counts = Counter()
    metrics = {}
    self_methods = {kind: Counter() for kind in (CPU_EVENT, ALLOCATION_EVENT)}
    inclusive_methods = {kind: Counter() for kind in (CPU_EVENT, ALLOCATION_EVENT)}
    classes, sites = Counter(), Counter()
    for kind in (CPU_EVENT, ALLOCATION_EVENT):
        metrics[kind] = {"total_samples": 0, "filtered_samples": 0, "total_samples_with_stack": 0,
                         "filtered_samples_with_stack": 0, "total_truncated_stacks": 0,
                         "filtered_truncated_stacks": 0, "filter_matches": Counter(),
                         "total_threads": Counter(), "filtered_threads": Counter(),
                         "first_filtered_timestamp": None, "last_filtered_timestamp": None}
    metrics[ALLOCATION_EVENT].update(total_weight_bytes=0, filtered_weight_bytes=0)

    for event in events:
        kind = event.get("type", "<missing event type>")
        event_counts[kind] += 1
        if kind not in metrics:
            continue
        values = event.get("values")
        if not isinstance(values, dict):
            raise ValueError(f"{kind} has no values object")
        stack = values.get("stackTrace") or {}
        methods = [method_key(frame) for frame in stack.get("frames", [])]
        thread = values.get("sampledThread" if kind == CPU_EVENT else "eventThread") or {}
        thread_name = thread.get("javaName") or thread.get("osName") or "<unknown thread>"
        thread_match = bool(thread_pattern.search(thread_name))
        stack_match = any(stack_pattern.search(method[0]) for method in methods)
        selected = thread_match or stack_match
        truncated = bool(stack.get("truncated", False))
        metric = metrics[kind]
        metric["total_samples"] += 1
        metric["total_samples_with_stack"] += bool(methods)
        metric["total_truncated_stacks"] += truncated
        metric["total_threads"][thread_name] += 1
        weight = 1
        if kind == ALLOCATION_EVENT:
            weight = values.get("weight")
            if isinstance(weight, bool) or not isinstance(weight, int) or weight < 0:
                raise ValueError(f"Invalid allocation sample weight: {weight!r}")
            metric["total_weight_bytes"] += weight
        if not selected:
            continue
        metric["filtered_samples"] += 1
        metric["filtered_samples_with_stack"] += bool(methods)
        metric["filtered_truncated_stacks"] += truncated
        metric["filtered_threads"][thread_name] += 1
        metric["filter_matches"]["both" if thread_match and stack_match else "thread_only" if thread_match else "stack_only"] += 1
        timestamp = values.get("startTime")
        if metric["first_filtered_timestamp"] is None:
            metric["first_filtered_timestamp"] = timestamp
        metric["last_filtered_timestamp"] = timestamp
        if methods:
            self_methods[kind][methods[0]] += weight
            for method in set(methods):
                inclusive_methods[kind][method] += weight
        if kind == ALLOCATION_EVENT:
            metric["filtered_weight_bytes"] += weight
            allocated_class = class_name(values.get("objectClass"))
            classes[allocated_class] += weight
            if methods:
                sites[(allocated_class, *methods[0])] += weight

    cpu, allocation = metrics[CPU_EVENT], metrics[ALLOCATION_EVENT]
    for metric in metrics.values():
        metric["filtered_sample_share_percent"] = percent(metric["filtered_samples"], metric["total_samples"])
        for key in ("filter_matches", "total_threads", "filtered_threads"):
            metric[key] = dict(sorted(metric[key].items(), key=lambda pair: (-pair[1], pair[0])))
    cpu["self_methods"] = ranked_methods(self_methods[CPU_EVENT], cpu["filtered_samples"], "samples")
    cpu["inclusive_methods"] = ranked_methods(inclusive_methods[CPU_EVENT], cpu["filtered_samples"], "samples")
    allocation["filtered_weight_share_percent"] = percent(allocation["filtered_weight_bytes"], allocation["total_weight_bytes"])
    allocation["self_methods"] = ranked_methods(self_methods[ALLOCATION_EVENT], allocation["filtered_weight_bytes"], "weight_bytes")
    allocation["inclusive_methods"] = ranked_methods(inclusive_methods[ALLOCATION_EVENT], allocation["filtered_weight_bytes"], "weight_bytes")
    allocation["classes"] = [{"class": key, "weight_bytes": value,
                              "percent_filtered": percent(value, allocation["filtered_weight_bytes"])}
                             for key, value in sorted(classes.items(), key=lambda pair: (-pair[1], pair[0]))]
    allocation["class_self_sites"] = [
        {"class": key[0], "method": key[1], "descriptor": key[2], "weight_bytes": value,
         "percent_filtered": percent(value, allocation["filtered_weight_bytes"])}
        for key, value in sorted(sites.items(), key=lambda pair: (-pair[1], pair[0]))]
    return {"schema_version": 1, "filters": {"logic": "thread OR any stack method", "thread_regex": thread_regex,
                                            "stack_regex": stack_regex}, "events_seen": dict(event_counts),
            "cpu": cpu, "allocation": allocation,
            "notes": ["CPU percentages are fractions of selected execution samples, not wall-clock time.",
                      "Allocation weight estimates bytes represented by samples; sample counts are not object counts.",
                      "Inclusive methods are deduplicated per stack; their percentages overlap and need not sum to 100%.",
                      "Self means the top recorded Java frame, not an exact native instruction or allocation count.",
                      "Missing-stack selected events remain in denominators; method tables omit those events.",
                      "The default selection covers benchmark worker threads and writer stacks, not arbitrary asynchronous query workers.",
                      "All matching events in the input are included, including any recorded setup or warmup.",
                      "Print JFR with --stack-depth 128; the default five-frame display can hide callers even when truncated=false."]}


def markdown(report, top=25):
    cpu, allocation = report["cpu"], report["allocation"]
    lines = ["# JFR binary writer profile summary", "", f"Input: `{report.get('input', '<stream>')}`", "",
             "Selection is a benchmark-thread match **or** a writer/benchmark method anywhere in the recorded stack.", "",
             "| Measure | All events | Selected events | Selected share |",
             "| --- | ---: | ---: | ---: |",
             f"| Execution samples | {cpu['total_samples']:,} | {cpu['filtered_samples']:,} | {cpu['filtered_sample_share_percent']:.2f}% |",
             f"| Allocation samples | {allocation['total_samples']:,} | {allocation['filtered_samples']:,} | {allocation['filtered_sample_share_percent']:.2f}% |",
             f"| Allocation weight, bytes | {allocation['total_weight_bytes']:,} | {allocation['filtered_weight_bytes']:,} | {allocation['filtered_weight_share_percent']:.2f}% |", "",
             f"Selected CPU samples with stacks: {cpu['filtered_samples_with_stack']:,}; "
             f"marked truncated: {cpu['filtered_truncated_stacks']:,}. Selected allocation samples with stacks: "
             f"{allocation['filtered_samples_with_stack']:,}; marked truncated: {allocation['filtered_truncated_stacks']:,}.", ""]

    def table(title, rows, label_key, value_key):
        allocation_table = value_key == "weight_bytes"
        label = "Class" if label_key == "class" else "Method (JVM descriptor retained)"
        lines.extend([f"## {title}", "", f"| {label} | {'Weight, MiB' if allocation_table else 'Samples'} | Selected share |",
                      "| --- | ---: | ---: |"])
        for row in rows[:top]:
            name = row[label_key] + (row.get("descriptor", "") if label_key == "method" else "")
            name = name.replace("|", "\\|").replace("`", "'")
            value = f"{row[value_key] / 1048576:,.3f}" if allocation_table else f"{row[value_key]:,}"
            lines.append(f"| `{name}` | {value} | {row['percent_filtered']:.2f}% |")
        if not rows:
            lines.append("| No matching samples | 0 | 0.00% |")
        lines.append("")

    table("CPU self attribution", cpu["self_methods"], "method", "samples")
    table("CPU inclusive attribution", cpu["inclusive_methods"], "method", "samples")
    table("Sampled allocation by class", allocation["classes"], "class", "weight_bytes")
    table("Sampled allocation by top frame", allocation["self_methods"], "method", "weight_bytes")
    table("Sampled allocation inclusive attribution", allocation["inclusive_methods"], "method", "weight_bytes")
    lines.extend(["## Interpretation", ""] + [f"- {note}" for note in report["notes"]] + [""])
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", type=Path, help="JSON produced by jfr print --json --stack-depth 128")
    parser.add_argument("--json", type=Path, help="Output JSON; defaults to INPUT_STEM.summary.json")
    parser.add_argument("--markdown", type=Path, help="Output Markdown; defaults to INPUT_STEM.summary.md")
    parser.add_argument("--top", type=int, default=25, help="Rows per Markdown table; JSON retains all methods")
    parser.add_argument("--thread-regex", default=DEFAULT_THREAD)
    parser.add_argument("--stack-regex", default=DEFAULT_STACK)
    args = parser.parse_args()
    if args.top < 1:
        parser.error("--top must be positive")
    try:
        report = summarize(iter_jfr_events(args.input), args.thread_regex, args.stack_regex)
        report["input"] = str(args.input.resolve())
        json_path = args.json or args.input.with_name(args.input.stem + ".summary.json")
        markdown_path = args.markdown or args.input.with_name(args.input.stem + ".summary.md")
        if args.input.resolve() in (json_path.resolve(), markdown_path.resolve()) or json_path.resolve() == markdown_path.resolve():
            parser.error("Input and output paths must be distinct")
        json_path.parent.mkdir(parents=True, exist_ok=True)
        markdown_path.parent.mkdir(parents=True, exist_ok=True)
        json_path.write_text(json.dumps(report, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        markdown_path.write_text(markdown(report, args.top), encoding="utf-8")
        print(f"CPU: {report['cpu']['filtered_samples']}/{report['cpu']['total_samples']} selected samples")
        print(f"Allocation: {report['allocation']['filtered_weight_bytes']}/{report['allocation']['total_weight_bytes']} selected weighted bytes")
        print(f"JSON: {json_path}\nMarkdown: {markdown_path}")
    except (OSError, ValueError, re.error) as failure:
        print(f"JFR summary failed: {failure}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
